idioms_data = []
id_counter = 1

def add_idiom(idiom, meaning, explanation, example, category, difficulty="intermediate", usage="both", origin="", related=None):
    global id_counter
    if related is None:
        related = []
    idioms_data.append({
        "id": id_counter,
        "idiom": idiom,
        "meaning": meaning,
        "explanation": explanation,
        "example": example,
        "usage": usage,
        "category": category,
        "difficulty": difficulty,
        "origin": origin,
        "related": related
    })
    id_counter += 1

